 export const TASA_IVA = 0.13;

+// Tasa de IVA configurable por entorno: TASA_IVA debe ser un número entre 0 y 1 (0.13 = 13 %).
+// Si no está definida, vale 0.13; cualquier otro valor inválido lanza RangeError.
+export function tasaIva(env = process.env) {
+  const valor = env.TASA_IVA;
+  if (valor === undefined) return TASA_IVA;
+  if (!/^\d*\.?\d+$/.test(valor)) throw new RangeError("TASA_IVA inválida: debe ser un número entre 0 y 1");
+  const tasa = Number(valor);
+  if (tasa > 1) throw new RangeError("TASA_IVA inválida: debe ser un número entre 0 y 1");
+  return tasa;
+}
+
